input.command:
S=/private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin--claude-worktrees-conversion-funnel-1f5b9e/e121a972-2fcb-4863-84bf-c169363ec7f7/scratchpad; cd "$S/scripts"
python3 -I - "$S/chats-raw" <<'EOF'
import sys, os, gzip, json, glob, re
root=sys.argv[1]
files=sorted(glob.glob(os.path.join(root,'*','*.json.gz')))
ws=[]; sr=[]; ss=[]; ex=[]; multi=0
for f in files:
    rec=json.loads(gzip.open(f).read())
    if rec['format']!='anthropic': continue
    req=json.loads(rec['request'])
    ids={}
    for m in req['messages']:
        c=m['content']
        if isinstance(c,str): continue
        texts=[b for b in c if b.get('type')=='text']
        if m['role']=='user' and texts:
            if len(texts)>1: multi+=1
            if texts[0]['text'].startswith('<workspace>') and len(ws)<4: ws.append(re.sub(r'\s+',' ',texts[0]['text'])[:100]+' ... '+re.sub(r'\s+',' ',texts[0]['text'])[-250:])
        for b in c:
            if b.get('type')=='tool_use': ids[b['id']]=b['name']
            if b.get('type')=='tool_result':
                name=ids.get(b['tool_use_id'])
                cc=b.get('content'); txt=cc if isinstance(cc,str) else ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                if name=='slice_report' and len(sr)<4: sr.append(txt[:500])
                if name=='slice_start' and len(ss)<2: ss.append(txt[:300])
                if name=='export_file' and len(ex)<2: ex.append(txt[:300])
print('user messages with >1 text block:', multi)
print('\n<workspace>-first user texts:'); [print(' -',x,'\n') for x in ws]
