"""POST /ent/jusprin/v2/launches: a start report from the desktop app becomes
one row, with nothing about a person on it."""
import json

from django.test import Client, TestCase

from jusprin.models import AppLaunch

URL = '/ent/jusprin/v2/launches'
INSTALL = '0123456789abcdef0123456789abcdef'
REPORT = {'install': INSTALL, 'app': 'JusPrin 2.0.0 (OrcaSlicer 2.5.0)', 'os': 'macOS Version 26.3 (Build 25D125)'}


class LaunchesTestCase(TestCase):
    def post(self, body):
        return Client().post(URL, data=body if isinstance(body, (str, bytes)) else json.dumps(body),
                             content_type='application/json', HTTP_USER_AGENT='JusPrin/2.0.0 OrcaSlicer/2.5.0')

    def test_a_start_is_one_row(self):
        self.assertEqual(self.post(REPORT).status_code, 204)
        launch = AppLaunch.objects.get()
        self.assertEqual((launch.install_id, launch.app, launch.os), (INSTALL, REPORT['app'], REPORT['os']))
        self.assertIsNotNone(launch.created_at)

    def test_every_start_of_an_install_counts(self):
        self.post(REPORT)
        self.post(REPORT)
        self.assertEqual(AppLaunch.objects.filter(install_id=INSTALL).count(), 2)

    def test_an_old_release_is_still_counted(self):
        with self.settings(JUSPRIN_V2_MIN_APP_VERSION='9.0.0'):
            self.assertEqual(self.post(REPORT).status_code, 204)

    def test_a_body_the_app_would_not_send_is_the_servers_error(self):
        for body in ({**REPORT, 'install': 'short'}, {**REPORT, 'email': 'a@b.c'}, {k: v for k, v in REPORT.items() if k != 'os'},
                     {**REPORT, 'app': 'x' * 201}, '[]', 'not json'):
            with self.subTest(body=body), self.assertRaises(ValueError if body != 'not json' else json.JSONDecodeError):
                self.post(body)
        self.assertEqual(AppLaunch.objects.count(), 0)

    def test_only_post(self):
        self.assertEqual(Client().get(URL).status_code, 405)

